"""S01 Triangle classification (Jorgensen 2013, ch. 7; Myers et al. 2011)."""


def decide(a, b, c):
    if a >= b + c or b >= a + c or c >= a + b:
        return "Not a triangle"
    if a == b and b == c:
        return "Equilateral"
    if a == b or b == c or a == c:
        return "Isosceles"
    return "Scalene"

"""S02 NextDate: which action produces the next date (Jorgensen 2013, ch. 7)."""


def is_leap(year):
    return (year % 4 == 0 and year % 100 != 0) or year % 400 == 0


def decide(day, month, year):
    if month == 2:
        if is_leap(year):
            last = 29
        else:
            last = 28
    elif month in (4, 6, 9, 11):
        last = 30
    else:
        last = 31
    if day > last:
        return "Invalid date"
    if day < last:
        return "Next day same month"
    if month == 12:
        return "First day of next year"
    return "First day of next month"

"""S03 Order discount with tiers, coupon, membership and a 30% cap."""


def decide(cart_value, coupon, member):
    if coupon == "invalid":
        return "REJECTED"
    if cart_value >= 5000:
        rate = 20
    elif cart_value >= 2000:
        rate = 10
    elif cart_value >= 1000:
        rate = 5
    else:
        rate = 0
    if coupon == "valid":
        rate = rate + 10
    if member:
        rate = rate + 5
    if rate > 30:
        rate = 30
    return str(rate) + "%"

"""S04 BMI level (Goossens et al. 2023, GPT-DMN 'BMI')."""


def decide(gender, weight, length):
    bmi = weight / (length * length)
    if bmi > 30:
        return "Obese"
    if bmi >= 25:
        if gender == "male":
            return "Normal"
        return "Overweight"
    if bmi >= 18.5:
        if gender == "male":
            return "Underweight"
        return "Normal"
    if gender == "male":
        return "Severely underweight"
    return "Underweight"

"""S05 Pet adoption (Goossens et al. 2023, GPT-DMN 'Determine pet')."""


def decide(allergies, time, kids, garden):
    if allergies:
        if time == "none":
            return "No pet"
        return "Fish"
    if time == "none" and not kids:
        return "No pet"
    if kids and time != "a lot":
        return "Fish"
    if garden:
        return "Dog"
    return "Cat"

"""S06 Driver's licence eligibility (Goossens et al. 2023, GPT-DMN "Driver's license")."""


def decide(age, national_resident, theory, driving, maneuvering, anticipation):
    if age < 18 or not national_resident:
        return "Not eligible"
    if "Fail" in (theory, driving, maneuvering, anticipation):
        return "Not eligible"
    return "Eligible"

"""S07 Vacation days (Goossens et al. 2023 'Holidays'; DMCommunity challenge Jan 2016, J. Vanthienen)."""


def decide(age, years_of_service):
    days = 22
    extra_five = age < 18 or age >= 60 or years_of_service >= 30
    if extra_five:
        days = days + 5
    if years_of_service >= 30 or age >= 60:
        days = days + 3
    if not extra_five and (15 <= years_of_service < 30 or age >= 45):
        days = days + 2
    return days

"""S08 Mode of transportation (Goossens et al. 2023, GPT-DMN; boundaries clarified)."""


def decide(distance, weather, hurry):
    if distance < 2:
        if hurry:
            return "bike"
        return "walk"
    if distance < 5:
        if weather == "rainy" or hurry:
            return "car"
        return "bike"
    if distance < 10:
        if weather == "rainy" or hurry or weather == "freezing":
            return "car"
        return "bike"
    if hurry or weather in ("rainy", "freezing"):
        return "car"
    return "bike"

"""S09 Scholarship eligibility (Goossens et al. 2023, GPT-DMN 'scholarship')."""


def decide(grades, annual_income, received_other_scholarship):
    if grades in ("excellent", "good") and annual_income < 50000 and not received_other_scholarship:
        return "Eligible"
    return "Not eligible"

"""S10 Login attempt with account lockout and OTP (authored for this benchmark)."""

MAX_FAILED = 4


def decide(account_locked, password_correct, failed_attempts, trusted_device, otp_verified):
    if account_locked:
        return "Account locked"
    if not password_correct:
        if failed_attempts >= MAX_FAILED:
            return "Account locked"
        return "Invalid credentials"
    if trusted_device or otp_verified:
        return "Access granted"
    return "OTP required"

"""S11 UPI transfer screening (authored for this benchmark; simplified, not an NPCI rule set)."""


def decide(amount, new_payee, registered_device):
    if amount > 100000:
        return "Blocked"
    if new_payee and amount > 5000:
        return "On hold"
    if not registered_device and amount > 2000:
        return "OTP required"
    return "Allowed"

"""S12 Personal-loan screening (authored for this benchmark)."""


def decide(age, credit_score, monthly_income, has_cosigner):
    if age < 21 or credit_score < 600:
        return "Rejected"
    if credit_score >= 750 or monthly_income >= 50000 or has_cosigner:
        return "Approved"
    return "Referred"
